mapper.select:
SELECT li.login_code AS id, t.tenant_code AS tenantCode, u.user_nm AS name, li.password_hash AS password, NULL AS ihidNum, u.email_adres AS email, CASE WHEN a.authority_code = 'PLATFORM_ADMIN' THEN 'ADM' ELSE 'USR' END AS userSe, u.department_id AS orgnztId, u.user_code AS uniqId, u.department_id AS groupId, d.department_code AS groupCode, CASE WHEN a.authority_code = 'PLATFORM_ADMIN' THEN 'ROLE_ADMIN' WHEN a.authority_code = 'TENANT_ADMIN' THEN 'ROLE_TENANT_ADMIN' ELSE 'ROLE_USER' END AS groupNm, a.authority_code AS roleCode FROM tb_login_account li JOIN tb_user u ON u.user_id = li.user_id JOIN tb_tenant t ON t.tenant_id = li.tenant_id JOIN tb_authority a ON a.authority_id = li.authority_id LEFT JOIN tb_department d ON d.department_id = u.department_id WHERE li.login_code = #{id} AND li.password_hash = #{password} AND t.tenant_code = #{tenantCode}
AND a.authority_code = #{roleCode}
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(u.use_at, 'Y') = 'Y' AND COALESCE(d.use_at, 'Y') = 'Y' AND COALESCE(t.use_at, 'Y') = 'Y' AND COALESCE(a.use_at, 'Y') = 'Y'

SELECT li.login_code AS id FROM tb_login_account li JOIN tb_user u ON u.user_id = li.user_id JOIN tb_tenant t ON t.tenant_id = li.tenant_id WHERE u.user_nm = #{name} AND u.email_adres = #{email}
AND t.tenant_code = #{tenantCode}
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(u.use_at, 'Y') = 'Y' AND COALESCE(t.use_at, 'Y') = 'Y' ORDER BY li.created_at DESC LIMIT 1

SELECT li.password_hash AS password FROM tb_login_account li JOIN tb_user u ON u.user_id = li.user_id JOIN tb_tenant t ON t.tenant_id = li.tenant_id WHERE li.login_code = #{id} AND u.user_nm = #{name} AND u.email_adres = #{email}
AND t.tenant_code = #{tenantCode}
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(u.use_at, 'Y') = 'Y' AND COALESCE(t.use_at, 'Y') = 'Y'
